-- Migration 28: VYBE Tickets increment 2 — risk engine, material event changes, verified reviews and private complaints,
-- promoter referrals, organiser exports, and scheduled housekeeping. Additive and re-runnable; no existing row is rewritten.
--
-- 1. Risk engine: configurable, explainable rules (risk_rules) open risk cases (risk_cases) from real events: an organiser
--    buying their own tickets, bursts of failed payments, sales spikes, high refund rates, repeated payout-detail changes,
--    lost chargebacks, duplicate events, bursts of invalid door scans, confirmed acts changed after approval, review
--    bursts, self-referrals. A case is a signal, never a verdict: only two outcomes act automatically and both are
--    reversible holds — a payout hold (PAUSE_PAYOUT) and a temporary purchase restriction (RESTRICT_ACCOUNT). Everything
--    else waits for a person. Rules and evidence are admin-only; organisers see a plain "on hold, under review" and can
--    appeal. False positives are dismissed with a recorded reason.
-- 2. Material changes: moving an event by more than an hour or changing its venue records a material change, tells
--    ticket holders, and makes refunds for earlier purchases immediate and complete (fee included) regardless of the
--    usual refund window. Organisers can also declare one (e.g. a headliner pulled out).
-- 3. Reviews: only people who held a ticket that was not fully refunded can review, after the event; "verified attendee"
--    only when their ticket was actually scanned at the door. Hosts and their organisation's members cannot review their
--    own events. Organisers respond publicly; moderation hides with a reason; reviews can be reported. Averages are not
--    shown below three reviews. Private complaints go to the organiser and can be escalated to VYBE.
-- 4. Promoter referrals: organisers create links with a promoter commission (paid from the organiser's share, never from
--    VYBE's commission). Attribution happens only for paid orders, never to the buyer themselves, and is reversed in
--    proportion to refunds and in full on a lost chargeback. Promoter earnings sit in their own journal account.
-- 5. Exports for organisers: sales (no buyer contact details) and the door list (names and ticket types).
-- 6. Housekeeping: if pg_cron is available it is enabled and lapsed holds, stuck refunds and the daily reconciliation run
--    on schedule.
--
-- Rollback: re-run create_order, request_refund, request_payout, admin_mark_payout_paid from migration 27 and
-- staff_report_context, staff_remove_content from migration 3; drop the triggers named trg_risk_* / trg_material_change /
-- trg_referral_*; new tables can stay.

-- ---------------------------------------------------------------- 0. security fix: can_view_finance returned NULL for outsiders
-- Since migration 8 it returned NULL (not false) for someone with no role, and `if not can_view_finance(...)` lets NULL
-- through: any signed-in member could read another organisation's payout balance or file a payout request for it (the money
-- would still have gone to that organisation's own verified account). Row policies were never affected (NULL denies).
create or replace function public.can_view_finance(p_org uuid, p_user uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce(public.is_admin() or (p_user is not null and p_user = auth.uid()) or (p_org is not null and public.org_role(p_org) in ('owner','admin')), false);
$$;

-- ---------------------------------------------------------------- 1. risk engine
create table if not exists public.risk_rules (
  key text primary key check (key ~ '^[a-z_]{3,40}$'),
  description text not null,
  enabled boolean not null default true,
  threshold integer not null default 1 check (threshold >= 1),
  window_minutes integer not null default 60 check (window_minutes between 0 and 525600),
  action text not null check (action in ('MONITOR', 'REQUIRE_ADDITIONAL_VERIFICATION', 'REQUIRE_MANUAL_REVIEW', 'LIMIT_SALES', 'PAUSE_PAYOUT', 'SUSPEND_EVENT', 'RESTRICT_ACCOUNT', 'ESCALATE_TO_TRUST_TEAM')),
  updated_by uuid references public.profiles(id) on delete set null,
  updated_at timestamptz not null default now()
);
insert into public.risk_rules (key, description, threshold, window_minutes, action) values
  ('organiser_self_purchase', 'A paid order for an event bought by its host or a member of the hosting organisation (possible circular sales).', 1, 0, 'MONITOR'),
  ('buyer_failed_payments', 'Several payments the gateway reported as failed, from one buyer in a short time (possible card testing). Purchases pause until reviewed. Cancelling a checkout does not count.', 5, 60, 'RESTRICT_ACCOUNT'),
  ('event_sales_spike', 'Unusually many paid orders for one event within the window.', 200, 60, 'MONITOR'),
  ('refund_rate_high', 'Refunds (percent of paid orders, at least 10 orders) above the threshold. Payouts hold until reviewed.', 30, 0, 'PAUSE_PAYOUT'),
  ('payout_account_churn', 'Payout bank details changed repeatedly within the window. Payouts hold until reviewed.', 2, 43200, 'PAUSE_PAYOUT'),
  ('chargeback_lost', 'A chargeback was lost on one of the organiser''s events.', 1, 0, 'REQUIRE_MANUAL_REVIEW'),
  ('duplicate_event', 'Another host lists an event with the same title at the same time (possible impersonation).', 1, 0, 'REQUIRE_MANUAL_REVIEW'),
  ('invalid_scans', 'Many invalid ticket codes presented at one event''s door within the window (possible counterfeits).', 50, 60, 'ESCALATE_TO_TRUST_TEAM'),
  ('lineup_changed_after_approval', 'A confirmed act was edited after ticket sales were approved.', 1, 0, 'REQUIRE_MANUAL_REVIEW'),
  ('review_burst', 'Many reviews for one event from accounts younger than 7 days within the window (possible manipulation).', 10, 60, 'MONITOR'),
  ('self_referral', 'A buyer tried to use their own promoter link.', 1, 0, 'MONITOR')
on conflict (key) do nothing;

create table if not exists public.risk_cases (
  id bigint generated always as identity primary key,
  rule_key text not null references public.risk_rules(key) on delete restrict,
  subject_type text not null check (subject_type in ('user', 'organization', 'event', 'order')),
  subject_id uuid not null,
  action text not null,
  status text not null default 'open' check (status in ('open', 'monitoring', 'appealed', 'actioned', 'dismissed')),
  evidence jsonb not null default '{}'::jsonb,
  appeal text not null default '' check (char_length(appeal) <= 2000),
  decision_note text not null default '' check (char_length(decision_note) <= 1000),
  decided_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  decided_at timestamptz
);
-- One live case per rule and subject; a closed case can be followed by a new one if the signal recurs.
create unique index if not exists risk_cases_live_key on public.risk_cases (rule_key, subject_type, subject_id) where status in ('open', 'monitoring', 'appealed');
create index if not exists risk_cases_subject_idx on public.risk_cases (subject_type, subject_id, status);
create index if not exists risk_cases_status_idx on public.risk_cases (status, created_at desc);
alter table public.risk_rules enable row level security;
alter table public.risk_cases enable row level security;
drop policy if exists risk_rules_read on public.risk_rules;
create policy risk_rules_read on public.risk_rules for select to authenticated using (public.is_admin());
drop policy if exists risk_cases_read on public.risk_cases;
create policy risk_cases_read on public.risk_cases for select to authenticated using (public.is_admin());
revoke all on public.risk_rules, public.risk_cases from anon, authenticated;
grant select on public.risk_rules, public.risk_cases to authenticated;

-- Opens a case if the rule is on. Returns true when a new case was opened.
create or replace function public.risk_signal(p_rule text, p_subject_type text, p_subject uuid, p_evidence jsonb) returns boolean
language plpgsql security definer set search_path = '' as $$
declare r public.risk_rules; n integer;
begin
  select * into r from public.risk_rules where key = p_rule;
  if not found or not r.enabled or p_subject is null then return false; end if;
  insert into public.risk_cases (rule_key, subject_type, subject_id, action, evidence)
  values (p_rule, p_subject_type, p_subject, r.action, coalesce(p_evidence, '{}'::jsonb))
  on conflict (rule_key, subject_type, subject_id) where status in ('open', 'monitoring', 'appealed') do nothing;
  get diagnostics n = row_count;
  if n > 0 then insert into public.audit_log (actor, action, entity_type, entity_id, detail) values (null, 'risk.case_opened', p_subject_type, p_subject, jsonb_build_object('rule', p_rule, 'action', r.action)); end if;
  return n > 0;
end $$;

-- Reversible automatic holds. Monitoring-only cases never block anything.
create or replace function public.payout_on_hold(p_org uuid, p_user uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.risk_cases c where c.action = 'PAUSE_PAYOUT' and c.status in ('open', 'appealed')
                   and ((p_org is not null and c.subject_type = 'organization' and c.subject_id = p_org) or (p_org is null and c.subject_type = 'user' and c.subject_id = p_user)));
$$;
create or replace function public.purchases_restricted(p_user uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.risk_cases c where c.action = 'RESTRICT_ACCOUNT' and c.status in ('open', 'appealed') and c.subject_type = 'user' and c.subject_id = p_user);
$$;

-- What an organiser may know about holds on their payouts: that there is one, and its appeal state. Never the rule.
create or replace function public.my_payout_holds(p_org uuid default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare u uuid := case when p_org is null then auth.uid() end;
begin
  if not public.can_view_finance(p_org, u) then raise exception 'forbidden' using errcode = '42501'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'since', c.created_at, 'status', c.status, 'appealed', c.appeal <> '') order by c.created_at)
                     from public.risk_cases c where c.action = 'PAUSE_PAYOUT' and c.status in ('open', 'appealed')
                      and ((p_org is not null and c.subject_type = 'organization' and c.subject_id = p_org) or (p_org is null and c.subject_type = 'user' and c.subject_id = u))), '[]'::jsonb);
end $$;
create or replace function public.appeal_payout_hold(p_case bigint, p_text text) returns void
language plpgsql security definer set search_path = '' as $$
declare c public.risk_cases;
begin
  select * into c from public.risk_cases where id = p_case for update;
  if not found or c.action <> 'PAUSE_PAYOUT' or c.status not in ('open', 'appealed') then raise exception 'Hold not found'; end if;
  if not public.can_view_finance(case when c.subject_type = 'organization' then c.subject_id end, case when c.subject_type = 'user' then c.subject_id end)
     or (c.subject_type = 'organization' and coalesce(public.org_role(c.subject_id) in ('owner', 'admin'), false) is false) then raise exception 'forbidden' using errcode = '42501'; end if;
  if coalesce(char_length(btrim(p_text)), 0) < 10 then raise exception 'Explain what happened (at least a sentence)'; end if;
  update public.risk_cases set status = 'appealed', appeal = left(btrim(p_text), 2000) where id = p_case;
  insert into public.audit_log (actor, action, entity_type, entity_id, detail) values (auth.uid(), 'risk.appealed', c.subject_type, c.subject_id, jsonb_build_object('case', p_case));
end $$;

create or replace function public.admin_decide_risk_case(p_case bigint, p_status text, p_note text) returns void
language plpgsql security definer set search_path = '' as $$
declare c public.risk_cases;
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_status not in ('monitoring', 'actioned', 'dismissed') then raise exception 'bad status'; end if;
  if coalesce(char_length(btrim(p_note)), 0) < 5 then raise exception 'Record the reason for this decision'; end if;
  select * into c from public.risk_cases where id = p_case for update;
  if not found then raise exception 'Case not found'; end if;
  if c.status in ('actioned', 'dismissed') then raise exception 'This case is already closed'; end if;
  update public.risk_cases set status = p_status, decision_note = left(btrim(p_note), 1000), decided_by = auth.uid(), decided_at = now() where id = p_case;
  insert into public.audit_log (actor, action, entity_type, entity_id, detail) values (auth.uid(), 'risk.' || p_status, c.subject_type, c.subject_id, jsonb_build_object('case', p_case, 'rule', c.rule_key, 'note', p_note));
end $$;

create or replace function public.admin_set_risk_rule(p_key text, p_enabled boolean, p_threshold integer, p_window integer, p_action text) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  update public.risk_rules set enabled = coalesce(p_enabled, enabled), threshold = coalesce(p_threshold, threshold), window_minutes = coalesce(p_window, window_minutes),
         action = coalesce(p_action, action), updated_by = auth.uid(), updated_at = now() where key = p_key;
  if not found then raise exception 'Unknown rule'; end if;
  insert into public.audit_log (actor, action, entity_type, detail) values (auth.uid(), 'risk.rule_updated', 'risk_rule', jsonb_build_object('key', p_key, 'enabled', p_enabled, 'threshold', p_threshold, 'window', p_window, 'action', p_action));
end $$;

-- Signals from orders: self-purchase and sales spikes when paid; failed-payment bursts when a payment fails.
create or replace function public.trg_risk_orders() returns trigger
language plpgsql security definer set search_path = '' as $$
declare ev public.events; r public.risk_rules; n integer;
begin
  if new.status is not distinct from old.status then return null; end if;
  if new.status = 'paid' and new.total_cents > 0 then
    select * into ev from public.events where id = new.event_id;
    if new.buyer = ev.host or (ev.organization_id is not null and exists (select 1 from public.organization_members m where m.organization_id = ev.organization_id and m.user_id = new.buyer and m.status = 'active')) then
      perform public.risk_signal('organiser_self_purchase', 'event', new.event_id, jsonb_build_object('order', new.id, 'total_cents', new.total_cents));
    end if;
    select * into r from public.risk_rules where key = 'event_sales_spike';
    if r.enabled then
      select count(*) into n from public.orders where event_id = new.event_id and status = 'paid' and paid_at > now() - make_interval(mins => r.window_minutes);
      if n >= r.threshold then perform public.risk_signal('event_sales_spike', 'event', new.event_id, jsonb_build_object('paid_orders', n, 'window_minutes', r.window_minutes)); end if;
    end if;
  elsif new.status = 'failed' and old.status = 'pending' then
    select * into r from public.risk_rules where key = 'buyer_failed_payments';
    if r.enabled then
      select count(*) into n from public.orders where buyer = new.buyer and status = 'failed' and created_at > now() - make_interval(mins => r.window_minutes);
      if n >= r.threshold then perform public.risk_signal('buyer_failed_payments', 'user', new.buyer, jsonb_build_object('failed_payments', n, 'window_minutes', r.window_minutes)); end if;
    end if;
  end if;
  return null;
end $$;
drop trigger if exists risk_orders on public.orders;
create trigger risk_orders after update of status on public.orders for each row execute function public.trg_risk_orders();

-- Refund rate per event, checked whenever a refund completes; the hold is on the event's payee.
create or replace function public.trg_risk_refunds() returns trigger
language plpgsql security definer set search_path = '' as $$
declare o public.orders; r public.risk_rules; paid integer; refunded integer; pay record;
begin
  if new.status <> 'succeeded' or old.status = 'succeeded' or new.kind = 'oversold' then return null; end if;
  select * into r from public.risk_rules where key = 'refund_rate_high';
  if not r.enabled then return null; end if;
  select * into o from public.orders where id = new.order_id;
  select count(*) filter (where status in ('paid', 'partially_refunded', 'refunded', 'disputed')), count(*) filter (where status in ('refunded', 'partially_refunded'))
    into paid, refunded from public.orders where event_id = o.event_id and total_cents > 0;
  if paid >= 10 and refunded * 100 >= r.threshold * paid then
    select * into pay from public.event_payee(o.event_id);
    perform public.risk_signal('refund_rate_high', case when pay.org is not null then 'organization' else 'user' end, coalesce(pay.org, pay.usr),
      jsonb_build_object('event', o.event_id, 'paid_orders', paid, 'refunded_orders', refunded));
  end if;
  return null;
end $$;
drop trigger if exists risk_refunds on public.refunds;
create trigger risk_refunds after update of status on public.refunds for each row execute function public.trg_risk_refunds();

create or replace function public.trg_risk_disputes() returns trigger
language plpgsql security definer set search_path = '' as $$
declare o public.orders; pay record;
begin
  if new.status <> 'lost' or old.status = 'lost' then return null; end if;
  select * into o from public.orders where id = new.order_id;
  select * into pay from public.event_payee(o.event_id);
  perform public.risk_signal('chargeback_lost', case when pay.org is not null then 'organization' else 'user' end, coalesce(pay.org, pay.usr), jsonb_build_object('order', o.id, 'dispute', new.id, 'amount_cents', new.amount_cents));
  return null;
end $$;
drop trigger if exists risk_disputes on public.disputes;
create trigger risk_disputes after update of status on public.disputes for each row execute function public.trg_risk_disputes();

-- Bank detail changes are written by the payout-account function, which also audits them.
create or replace function public.trg_risk_payout_accounts() returns trigger
language plpgsql security definer set search_path = '' as $$
declare r public.risk_rules; n integer;
begin
  if tg_op = 'UPDATE' and new.details_enc is not distinct from old.details_enc then return null; end if;
  select * into r from public.risk_rules where key = 'payout_account_churn';
  if not r.enabled then return null; end if;
  select count(*) into n from public.audit_log where entity_type = 'payout_account' and entity_id = new.id and action in ('payout_account.created', 'payout_account.updated')
     and created_at > now() - make_interval(mins => r.window_minutes);
  if tg_op = 'UPDATE' and n + 1 >= r.threshold then
    perform public.risk_signal('payout_account_churn', case when new.organization_id is not null then 'organization' else 'user' end, coalesce(new.organization_id, new.user_id),
      jsonb_build_object('changes_in_window', n + 1, 'window_minutes', r.window_minutes));
  end if;
  return null;
end $$;
drop trigger if exists risk_payout_accounts on public.payout_accounts;
create trigger risk_payout_accounts after insert or update on public.payout_accounts for each row execute function public.trg_risk_payout_accounts();

create or replace function public.trg_risk_duplicate_event() returns trigger
language plpgsql security definer set search_path = '' as $$
declare other uuid;
begin
  if new.status <> 'active' then return null; end if;
  select e.id into other from public.events e
   where e.id <> new.id and e.status = 'active' and e.host <> new.host and lower(btrim(e.title)) = lower(btrim(new.title))
     and abs(extract(epoch from e.starts_at - new.starts_at)) <= 3600 and e.organization_id is distinct from new.organization_id limit 1;
  if other is not null then perform public.risk_signal('duplicate_event', 'event', new.id, jsonb_build_object('looks_like', other)); end if;
  return null;
end $$;
drop trigger if exists risk_duplicate_event on public.events;
create trigger risk_duplicate_event after insert or update of title, starts_at, status on public.events for each row execute function public.trg_risk_duplicate_event();

create or replace function public.trg_risk_scans() returns trigger
language plpgsql security definer set search_path = '' as $$
declare r public.risk_rules; n integer;
begin
  if new.result <> 'invalid' or new.event_id is null then return null; end if;
  select * into r from public.risk_rules where key = 'invalid_scans';
  if not r.enabled then return null; end if;
  select count(*) into n from public.ticket_scans where event_id = new.event_id and result = 'invalid' and created_at > now() - make_interval(mins => r.window_minutes);
  if n >= r.threshold then perform public.risk_signal('invalid_scans', 'event', new.event_id, jsonb_build_object('invalid_scans', n, 'window_minutes', r.window_minutes)); end if;
  return null;
end $$;
drop trigger if exists risk_scans on public.ticket_scans;
create trigger risk_scans after insert on public.ticket_scans for each row execute function public.trg_risk_scans();

create or replace function public.trg_risk_lineup() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.status = 'changed' and old.status = 'confirmed' and (select sales_review from public.events where id = new.event_id) = 'approved' then
    perform public.risk_signal('lineup_changed_after_approval', 'event', new.event_id, jsonb_build_object('lineup', new.id, 'before', old.name, 'after', new.name));
  end if;
  return null;
end $$;
drop trigger if exists risk_lineup on public.event_lineup;
create trigger risk_lineup after update on public.event_lineup for each row execute function public.trg_risk_lineup();

-- ---------------------------------------------------------------- 2. material changes
alter table public.events add column if not exists material_change_at timestamptz;
alter table public.events add column if not exists material_change_note text not null default '' check (char_length(material_change_note) <= 500);

create or replace function public.notify_ticket_holders(p_event uuid, p_key text) returns integer
language plpgsql security definer set search_path = '' as $$
declare u uuid; n integer := 0;
begin
  for u in select distinct t.owner from public.tickets t where t.event_id = p_event and t.status in ('valid', 'used') loop
    perform public.notify(u, 'event_update', null, 'event', p_event, p_key); n := n + 1;
  end loop;
  return n;
end $$;

-- A move of more than an hour or a new venue is a material change: earlier buyers may cancel for a full refund.
create or replace function public.trg_material_change() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if (abs(extract(epoch from new.starts_at - old.starts_at)) > 3600
      or new.venue is distinct from old.venue or new.address is distinct from old.address or new.city is distinct from old.city)
     and exists (select 1 from public.tickets t where t.event_id = new.id and t.status = 'valid') then
    new.material_change_at := now();
    new.material_change_note := left(case when abs(extract(epoch from new.starts_at - old.starts_at)) > 3600 then 'Date or time changed. ' else '' end
                                     || case when (new.venue, new.address, new.city) is distinct from (old.venue, old.address, old.city) then 'Venue changed.' else '' end, 500);
    -- Holders are already told by the event_notify trigger (migration 10), with its own dedupe key: no second message here.
    insert into public.audit_log (actor, action, entity_type, entity_id, detail) values (auth.uid(), 'event.material_change', 'event', new.id,
      jsonb_build_object('starts_from', old.starts_at, 'starts_to', new.starts_at, 'venue_from', old.venue, 'venue_to', new.venue));
  end if;
  return new;
end $$;
drop trigger if exists material_change on public.events;
create trigger material_change before update of starts_at, venue, address, city on public.events for each row execute function public.trg_material_change();

create or replace function public.declare_material_change(p_event uuid, p_note text) returns integer
language plpgsql security definer set search_path = '' as $$
declare n integer;
begin
  if not public.can_manage_event(p_event) then raise exception 'forbidden' using errcode = '42501'; end if;
  if coalesce(char_length(btrim(p_note)), 0) < 5 then raise exception 'Tell ticket holders what changed'; end if;
  update public.events set material_change_at = now(), material_change_note = left(btrim(p_note), 500) where id = p_event;
  n := public.notify_ticket_holders(p_event, 'mc:' || p_event || ':' || extract(epoch from now())::bigint);
  insert into public.audit_log (actor, action, entity_type, entity_id, detail) values (auth.uid(), 'event.material_change_declared', 'event', p_event, jsonb_build_object('note', p_note, 'holders_told', n));
  return n;
end $$;

-- ---------------------------------------------------------------- 3. reviews and complaints
alter table public.notifications drop constraint if exists notifications_type_check;
alter table public.notifications add constraint notifications_type_check check (type in
  ('friend_request', 'friend_accepted', 'reaction', 'comment', 'event_invite', 'rsvp', 'community_join', 'new_event', 'event_update', 'event_cancelled', 'live_started',
   'post_tag', 'memory_reaction', 'memory_reply', 'verified', 'security', 'campaign', 'org_member', 'org_rsvp', 'org_follow',
   'ticket_order', 'refund_update', 'sales_review', 'payout_update', 'event_feedback'));
create table if not exists public.event_reviews (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null references public.events(id) on delete cascade,
  author uuid not null references public.profiles(id) on delete cascade,
  rating smallint not null check (rating between 1 and 5),
  body text not null default '' check (char_length(body) <= 2000),
  verified_attendee boolean not null default false,
  status text not null default 'published' check (status in ('published', 'hidden')),
  moderation_note text not null default '' check (char_length(moderation_note) <= 500),
  organiser_response text not null default '' check (char_length(organiser_response) <= 1000),
  responded_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (event_id, author)
);
create index if not exists event_reviews_event_idx on public.event_reviews (event_id, created_at desc);
create index if not exists event_reviews_author_idx on public.event_reviews (author);
alter table public.event_reviews enable row level security;
drop policy if exists event_reviews_read on public.event_reviews;
create policy event_reviews_read on public.event_reviews for select to authenticated
  using ((status = 'published' and public.can_view_event_id(event_id)) or author = (select auth.uid()) or public.is_admin());
revoke all on public.event_reviews from anon, authenticated;
grant select on public.event_reviews to authenticated;

-- Who may review: held a ticket (not fully refunded), after the event, not the host or their organisation.
create or replace function public.review_eligibility(p_event uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare ev public.events; held boolean; attended boolean;
begin
  select * into ev from public.events where id = p_event;
  if not found or auth.uid() is null then return jsonb_build_object('eligible', false, 'reason', 'not_found'); end if;
  if ev.host = auth.uid() or (ev.organization_id is not null and public.org_role(ev.organization_id) is not null) then return jsonb_build_object('eligible', false, 'reason', 'organiser'); end if;
  select exists (select 1 from public.tickets t join public.orders o on o.id = t.order_id where t.event_id = p_event and t.owner = auth.uid() and t.status in ('valid', 'used') and o.status in ('paid', 'partially_refunded')),
         exists (select 1 from public.tickets t where t.event_id = p_event and t.owner = auth.uid() and t.status = 'used')
    into held, attended;
  if not held then return jsonb_build_object('eligible', false, 'reason', 'no_ticket'); end if;
  if coalesce(ev.ends_at, ev.starts_at + interval '6 hours') > now() then return jsonb_build_object('eligible', false, 'reason', 'not_over'); end if;
  if coalesce(ev.ends_at, ev.starts_at + interval '6 hours') < now() - interval '60 days' then return jsonb_build_object('eligible', false, 'reason', 'too_late'); end if;
  return jsonb_build_object('eligible', true, 'verified_attendee', attended);
end $$;

create or replace function public.submit_event_review(p_event uuid, p_rating integer, p_body text) returns uuid
language plpgsql security definer set search_path = '' as $$
declare el jsonb; rid uuid; r public.risk_rules; n integer;
begin
  el := public.review_eligibility(p_event);
  if not (el->>'eligible')::boolean then
    raise exception '%', case el->>'reason' when 'organiser' then 'Organisers cannot review their own events' when 'no_ticket' then 'Only ticket holders can review this event'
                              when 'not_over' then 'You can review once the event is over' when 'too_late' then 'Reviews close 60 days after the event' else 'Not available' end;
  end if;
  if p_rating is null or p_rating not between 1 and 5 then raise exception 'Rate from 1 to 5'; end if;
  insert into public.event_reviews (event_id, author, rating, body, verified_attendee)
  values (p_event, auth.uid(), p_rating, left(coalesce(btrim(p_body), ''), 2000), (el->>'verified_attendee')::boolean)
  on conflict (event_id, author) do update set rating = excluded.rating, body = excluded.body, verified_attendee = excluded.verified_attendee, updated_at = now()
  returning id into rid;
  select * into r from public.risk_rules where key = 'review_burst';
  if r.enabled then
    select count(*) into n from public.event_reviews rv join public.profiles pr on pr.id = rv.author
     where rv.event_id = p_event and rv.created_at > now() - make_interval(mins => r.window_minutes) and pr.created_at > now() - interval '7 days';
    if n >= r.threshold then perform public.risk_signal('review_burst', 'event', p_event, jsonb_build_object('new_account_reviews', n)); end if;
  end if;
  return rid;
end $$;

create or replace function public.respond_to_review(p_review uuid, p_text text) returns void
language plpgsql security definer set search_path = '' as $$
declare rv public.event_reviews;
begin
  select * into rv from public.event_reviews where id = p_review;
  if not found or not public.can_manage_event(rv.event_id) then raise exception 'forbidden' using errcode = '42501'; end if;
  update public.event_reviews set organiser_response = left(coalesce(btrim(p_text), ''), 1000), responded_at = now() where id = p_review;
end $$;

create or replace function public.admin_moderate_review(p_review uuid, p_status text, p_note text) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not public.is_staff() then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_status not in ('published', 'hidden') then raise exception 'bad status'; end if;
  if p_status = 'hidden' and coalesce(char_length(btrim(p_note)), 0) < 5 then raise exception 'Give the reason for hiding it'; end if;
  update public.event_reviews set status = p_status, moderation_note = left(coalesce(p_note, ''), 500) where id = p_review;
  if not found then raise exception 'Review not found'; end if;
  insert into public.audit_log (actor, action, entity_type, entity_id, detail) values (auth.uid(), 'review.' || p_status, 'event_review', p_review, jsonb_build_object('note', p_note));
end $$;

-- Public summary; no average until there are at least three reviews (one or two opinions are not a score).
create or replace function public.event_review_summary(p_event uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('count', count(*), 'verified', count(*) filter (where verified_attendee),
                            'average', case when count(*) >= 3 then round(avg(rating)::numeric, 1) end)
  from public.event_reviews where event_id = p_event and status = 'published' and public.can_view_event_id(p_event);
$$;

create table if not exists public.event_complaints (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null references public.events(id) on delete cascade,
  author uuid not null references public.profiles(id) on delete cascade,
  order_id uuid references public.orders(id) on delete set null,
  subject text not null check (char_length(subject) between 3 and 120),
  body text not null check (char_length(body) between 10 and 4000),
  status text not null default 'open' check (status in ('open', 'answered', 'escalated', 'closed')),
  organiser_reply text not null default '' check (char_length(organiser_reply) <= 4000),
  replied_at timestamptz,
  resolution text not null default '' check (char_length(resolution) <= 1000),
  created_at timestamptz not null default now()
);
create index if not exists event_complaints_event_idx on public.event_complaints (event_id, created_at desc);
create index if not exists event_complaints_author_idx on public.event_complaints (author);
create index if not exists event_complaints_order_idx on public.event_complaints (order_id) where order_id is not null;
create index if not exists event_complaints_status_idx on public.event_complaints (status) where status = 'escalated';
alter table public.event_complaints enable row level security;
drop policy if exists complaints_read on public.event_complaints;
create policy complaints_read on public.event_complaints for select to authenticated
  using (author = (select auth.uid()) or public.can_manage_event(event_id) or public.is_admin());
revoke all on public.event_complaints from anon, authenticated;
grant select on public.event_complaints to authenticated;

create or replace function public.submit_complaint(p_event uuid, p_subject text, p_body text) returns uuid
language plpgsql security definer set search_path = '' as $$
declare oid uuid; cid uuid;
begin
  select o.id into oid from public.orders o where o.event_id = p_event and o.buyer = auth.uid() and o.status in ('paid', 'partially_refunded', 'refunded', 'disputed', 'failed') order by o.created_at desc limit 1;
  if oid is null and not exists (select 1 from public.tickets t where t.event_id = p_event and t.owner = auth.uid()) then raise exception 'Complaints are for people who bought or hold tickets'; end if;
  if (select count(*) from public.event_complaints where author = auth.uid() and created_at > now() - interval '1 day') >= 5 then raise exception 'Slow down a little'; end if;
  insert into public.event_complaints (event_id, author, order_id, subject, body) values (p_event, auth.uid(), oid, btrim(p_subject), btrim(p_body)) returning id into cid;
  perform public.notify((select host from public.events where id = p_event), 'event_feedback', auth.uid(), 'event', p_event, 'complaint:' || cid);
  return cid;
end $$;
create or replace function public.reply_complaint(p_complaint uuid, p_text text) returns void
language plpgsql security definer set search_path = '' as $$
declare c public.event_complaints;
begin
  select * into c from public.event_complaints where id = p_complaint for update;
  if not found or not public.can_manage_event(c.event_id) then raise exception 'forbidden' using errcode = '42501'; end if;
  if coalesce(char_length(btrim(p_text)), 0) < 5 then raise exception 'Write a reply'; end if;
  update public.event_complaints set organiser_reply = left(btrim(p_text), 4000), replied_at = now(), status = case when status = 'open' then 'answered' else status end where id = p_complaint;
  perform public.notify(c.author, 'event_feedback', auth.uid(), 'event', c.event_id, 'complaint-reply:' || c.id || ':' || extract(epoch from now())::bigint);
end $$;
create or replace function public.escalate_complaint(p_complaint uuid) returns void
language plpgsql security definer set search_path = '' as $$
begin
  update public.event_complaints set status = 'escalated' where id = p_complaint and author = auth.uid() and status in ('open', 'answered');
  if not found then raise exception 'Complaint not found or already closed'; end if;
  insert into public.audit_log (actor, action, entity_type, entity_id) values (auth.uid(), 'complaint.escalated', 'event_complaint', p_complaint);
end $$;
create or replace function public.admin_close_complaint(p_complaint uuid, p_resolution text) returns void
language plpgsql security definer set search_path = '' as $$
declare c public.event_complaints;
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  if coalesce(char_length(btrim(p_resolution)), 0) < 5 then raise exception 'Record the resolution'; end if;
  update public.event_complaints set status = 'closed', resolution = left(btrim(p_resolution), 1000) where id = p_complaint returning * into c;
  if not found then raise exception 'Complaint not found'; end if;
  perform public.notify(c.author, 'event_feedback', null, 'event', c.event_id, 'complaint-closed:' || c.id);
  insert into public.audit_log (actor, action, entity_type, entity_id, detail) values (auth.uid(), 'complaint.closed', 'event_complaint', p_complaint, jsonb_build_object('resolution', p_resolution));
end $$;

-- Reviews can be reported like other content; staff see and hide them through the existing audited moderation.
do $$ begin
  alter table public.reports drop constraint if exists reports_entity_type_check;
  alter table public.reports add constraint reports_entity_type_check check (entity_type in ('profile','post','comment','message','community','event','stream','event_review'));
end $$;
create or replace function public.staff_report_context(rid uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare r public.reports; ctx jsonb;
begin
  if not public.is_staff() then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into r from public.reports where id = rid;
  if not found then raise exception 'report not found'; end if;
  ctx := case r.entity_type
    when 'post' then (select jsonb_build_object('text', body, 'author', author, 'media', media_path is not null) from public.posts where id = r.entity_id)
    when 'comment' then (select jsonb_build_object('text', body, 'author', author) from public.comments where id = r.entity_id)
    when 'message' then (select jsonb_build_object('text', body, 'author', sender) from public.messages where id = r.entity_id)
    when 'event' then (select jsonb_build_object('text', title || E'\n' || description, 'author', host) from public.events where id = r.entity_id)
    when 'community' then (select jsonb_build_object('text', name || E'\n' || description, 'author', created_by) from public.communities where id = r.entity_id)
    when 'profile' then (select jsonb_build_object('text', username || E'\n' || display_name || E'\n' || bio, 'author', id) from public.profiles where id = r.entity_id)
    when 'stream' then (select jsonb_build_object('text', title, 'author', host) from public.live_streams where id = r.entity_id)
    when 'event_review' then (select jsonb_build_object('text', rating || '★ ' || body, 'author', author, 'verified_attendee', verified_attendee) from public.event_reviews where id = r.entity_id)
  end;
  insert into public.audit_log (actor, action, entity_type, entity_id, detail)
  values (auth.uid(), 'report.context_viewed', r.entity_type, r.entity_id, jsonb_build_object('report', rid));
  return coalesce(ctx, jsonb_build_object('text', null, 'gone', true));
end $$;
create or replace function public.staff_remove_content(rid uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare r public.reports;
begin
  if not public.is_staff() then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into r from public.reports where id = rid;
  if not found then raise exception 'report not found'; end if;
  case r.entity_type
    when 'post' then delete from public.posts where id = r.entity_id;
    when 'comment' then delete from public.comments where id = r.entity_id;
    when 'event' then update public.events set status = 'cancelled' where id = r.entity_id;
    when 'community' then delete from public.communities where id = r.entity_id;
    when 'stream' then update public.live_streams set status = 'cancelled' where id = r.entity_id and status = 'scheduled';
    when 'message' then update public.messages set body = 'Message removed', deleted_at = now() where id = r.entity_id;
    when 'event_review' then update public.event_reviews set status = 'hidden', moderation_note = 'Removed after a report' where id = r.entity_id;   -- hidden, not deleted: the author still sees why
    else raise exception 'this content type cannot be removed from here';
  end case;
  update public.reports set status = 'actioned' where id = rid;
  insert into public.audit_log (actor, action, entity_type, entity_id, detail)
  values (auth.uid(), 'content.removed', r.entity_type, r.entity_id, jsonb_build_object('report', rid));
end $$;

-- ---------------------------------------------------------------- 4. promoter referrals
-- Promoter earnings get their own journal account; the payee check now covers both payable accounts.
do $$ declare c record; begin
  for c in select conname from pg_constraint where conrelid = 'public.journal_lines'::regclass and contype = 'c' and conname <> 'journal_lines_amount_cents_check' loop
    execute format('alter table public.journal_lines drop constraint %I', c.conname);
  end loop;
end $$;
alter table public.journal_lines add constraint journal_lines_account_known check (account in ('platform_cash', 'organizer_payable', 'promoter_payable', 'refunds_payable', 'buyer_fee_revenue', 'commission_revenue', 'vat_payable', 'chargeback_losses', 'adjustments'));
alter table public.journal_lines add constraint journal_lines_payee_shape check (((account in ('organizer_payable', 'promoter_payable')) = (organization_id is not null or payee_user is not null)) and (organization_id is null or payee_user is null) and (account <> 'promoter_payable' or payee_user is not null));

create table if not exists public.promoter_links (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null references public.events(id) on delete cascade,
  promoter uuid not null references public.profiles(id) on delete cascade,
  code text not null unique check (code ~ '^[A-Z0-9]{8}$'),
  commission_bps integer not null check (commission_bps between 0 and 3000),
  active boolean not null default true,
  created_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  unique (event_id, promoter)
);
create index if not exists promoter_links_promoter_idx on public.promoter_links (promoter);
alter table public.promoter_links enable row level security;
drop policy if exists promoter_links_read on public.promoter_links;
create policy promoter_links_read on public.promoter_links for select to authenticated using (promoter = (select auth.uid()) or public.can_manage_event(event_id) or public.is_admin());
revoke all on public.promoter_links from anon, authenticated;
grant select on public.promoter_links to authenticated;

alter table public.orders add column if not exists referral_link_id uuid references public.promoter_links(id) on delete set null;
create index if not exists orders_referral_idx on public.orders (referral_link_id) where referral_link_id is not null;

create table if not exists public.referral_attributions (
  order_id uuid primary key references public.orders(id) on delete restrict,
  link_id uuid not null references public.promoter_links(id) on delete restrict,
  promoter uuid not null references public.profiles(id) on delete restrict,
  commission_bps integer not null,
  commission_cents bigint not null check (commission_cents >= 0),
  reversed_cents bigint not null default 0 check (reversed_cents >= 0),
  status text not null default 'earned' check (status in ('earned', 'partially_reversed', 'reversed')),
  created_at timestamptz not null default now(),
  check (reversed_cents <= commission_cents)
);
create index if not exists referral_attributions_link_idx on public.referral_attributions (link_id);
create index if not exists referral_attributions_promoter_idx on public.referral_attributions (promoter);
alter table public.referral_attributions enable row level security;
drop policy if exists referral_read on public.referral_attributions;
create policy referral_read on public.referral_attributions for select to authenticated
  using (promoter = (select auth.uid()) or public.is_admin() or exists (select 1 from public.orders o where o.id = order_id and public.can_manage_event(o.event_id)));
revoke all on public.referral_attributions from anon, authenticated;
grant select on public.referral_attributions to authenticated;

create or replace function public.create_promoter_link(p_event uuid, p_username text, p_commission_bps integer) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare pid uuid; ev public.events; c text; l public.promoter_links;
begin
  if not public.can_manage_event(p_event) then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into ev from public.events where id = p_event;
  select id into pid from public.profiles where username = lower(btrim(replace(coalesce(p_username, ''), '@', '')));
  if pid is null then raise exception 'No one on VYBE has that username'; end if;
  if pid = ev.host or (ev.organization_id is not null and exists (select 1 from public.organization_members m where m.organization_id = ev.organization_id and m.user_id = pid and m.status = 'active')) then
    raise exception 'Promoters must be outside the organising team';
  end if;
  if p_commission_bps is null or p_commission_bps not between 0 and 3000 then raise exception 'Commission is 0 to 30 %%'; end if;
  loop
    c := upper(substr(md5(gen_random_uuid()::text), 1, 8));
    exit when not exists (select 1 from public.promoter_links where code = c);
  end loop;
  insert into public.promoter_links (event_id, promoter, code, commission_bps, created_by) values (p_event, pid, c, p_commission_bps, auth.uid())
  on conflict (event_id, promoter) do update set commission_bps = excluded.commission_bps, active = true
  returning * into l;
  insert into public.audit_log (actor, action, entity_type, entity_id, detail) values (auth.uid(), 'promoter_link.saved', 'event', p_event, jsonb_build_object('promoter', pid, 'bps', p_commission_bps));
  return jsonb_build_object('id', l.id, 'code', l.code, 'commission_bps', l.commission_bps);
end $$;
create or replace function public.set_promoter_link_active(p_link uuid, p_active boolean) returns void
language plpgsql security definer set search_path = '' as $$
declare l public.promoter_links;
begin
  select * into l from public.promoter_links where id = p_link;
  if not found or not public.can_manage_event(l.event_id) then raise exception 'forbidden' using errcode = '42501'; end if;
  update public.promoter_links set active = p_active where id = p_link;
end $$;

-- When a referred order is paid: the promoter earns their share of the organiser's net, moved between payables.
create or replace function public.trg_referral_paid() returns trigger
language plpgsql security definer set search_path = '' as $$
declare l public.promoter_links; amt bigint; pay record;
begin
  if new.referral_link_id is null or new.status <> 'paid' or old.status = 'paid' then return null; end if;
  select * into l from public.promoter_links where id = new.referral_link_id;
  if not found or l.promoter = new.buyer then return null; end if;
  amt := public.bps_of(coalesce(new.organizer_net_cents, new.subtotal_cents), l.commission_bps);
  insert into public.referral_attributions (order_id, link_id, promoter, commission_bps, commission_cents) values (new.id, l.id, l.promoter, l.commission_bps, amt) on conflict (order_id) do nothing;
  if not found or amt = 0 then return null; end if;
  select * into pay from public.event_payee(new.event_id);
  insert into public.ledger_entries (event_id, organization_id, payee_user, order_id, kind, amount_cents, note) values (new.event_id, pay.org, pay.usr, new.id, 'adjustment', -amt, 'Promoter commission');
  perform public.post_journal('adjustment', 'referral:' || new.id, jsonb_build_object('event', new.event_id, 'order', new.id), jsonb_build_array(
    jsonb_build_object('account', 'organizer_payable', 'amount', amt, 'org', pay.org, 'user', pay.usr),
    jsonb_build_object('account', 'promoter_payable', 'amount', -amt, 'user', l.promoter)), 'Promoter commission');
  return null;
end $$;
drop trigger if exists referral_paid on public.orders;
create trigger referral_paid after update of status on public.orders for each row execute function public.trg_referral_paid();

-- Refunds and lost chargebacks give the promoter's share back to the organiser, in proportion.
create or replace function public.reverse_referral(p_order uuid, p_fraction_num bigint, p_fraction_den bigint, p_key text) returns void
language plpgsql security definer set search_path = '' as $$
declare a public.referral_attributions; o public.orders; pay record; amt bigint;
begin
  select * into a from public.referral_attributions where order_id = p_order for update;
  if not found or a.status = 'reversed' or p_fraction_den <= 0 then return; end if;
  if exists (select 1 from public.journal_entries where idempotency_key = p_key) then return; end if;
  amt := least(a.commission_cents - a.reversed_cents, div(a.commission_cents::numeric * p_fraction_num + div(p_fraction_den, 2), p_fraction_den)::bigint);
  if amt <= 0 then return; end if;
  select * into o from public.orders where id = p_order;
  select * into pay from public.event_payee(o.event_id);
  insert into public.ledger_entries (event_id, organization_id, payee_user, order_id, kind, amount_cents, note) values (o.event_id, pay.org, pay.usr, o.id, 'adjustment', amt, 'Promoter commission reversed');
  perform public.post_journal('adjustment', p_key, jsonb_build_object('event', o.event_id, 'order', o.id), jsonb_build_array(
    jsonb_build_object('account', 'promoter_payable', 'amount', amt, 'user', a.promoter),
    jsonb_build_object('account', 'organizer_payable', 'amount', -amt, 'org', pay.org, 'user', pay.usr)), 'Promoter commission reversed');
  update public.referral_attributions set reversed_cents = reversed_cents + amt,
         status = case when reversed_cents + amt >= commission_cents then 'reversed' else 'partially_reversed' end where order_id = p_order;
end $$;
create or replace function public.trg_referral_refund() returns trigger
language plpgsql security definer set search_path = '' as $$
declare o public.orders;
begin
  if new.status <> 'succeeded' or old.status = 'succeeded' or new.kind = 'oversold' then return null; end if;
  select * into o from public.orders where id = new.order_id;
  if o.subtotal_cents > 0 then perform public.reverse_referral(o.id, new.ticket_amount_cents, o.subtotal_cents, 'referral-refund:' || new.id); end if;
  return null;
end $$;
drop trigger if exists referral_refund on public.refunds;
create trigger referral_refund after update of status on public.refunds for each row execute function public.trg_referral_refund();
create or replace function public.trg_referral_chargeback() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.status = 'lost' and old.status <> 'lost' then perform public.reverse_referral(new.order_id, 1, 1, 'referral-chargeback:' || new.id); end if;
  return null;
end $$;
drop trigger if exists referral_chargeback on public.disputes;
create trigger referral_chargeback after update of status on public.disputes for each row execute function public.trg_referral_chargeback();

create or replace function public.my_promoter_earnings() returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('link', l.id, 'code', l.code, 'event_id', l.event_id, 'event', e.title, 'commission_bps', l.commission_bps, 'active', l.active,
           'orders', (select count(*) from public.referral_attributions a where a.link_id = l.id),
           'earned_cents', (select coalesce(sum(a.commission_cents - a.reversed_cents), 0) from public.referral_attributions a where a.link_id = l.id)) order by l.created_at desc), '[]'::jsonb)
  from public.promoter_links l join public.events e on e.id = l.event_id where l.promoter = auth.uid();
$$;


-- ---------------------------------------------------------------- migration 27 functions with this migration's rules
-- create_order: purchase restriction (risk) and promoter attribution.
create or replace function public.create_order(p_event uuid, p_items jsonb, p_provider text, p_idem text, p_ref text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  uid uuid := auth.uid(); ev public.events; cfg public.platform_config; ord public.orders; pol public.fee_policies; snap jsonb;
  it jsonb; tt public.ticket_types; q integer; subtotal bigint := 0; total_units integer := 0; mine integer; link public.promoter_links;
begin
  if uid is null then raise exception 'Sign in to buy tickets' using errcode = '28000'; end if;
  if exists (select 1 from public.buyer_flags where user_id = uid) then raise exception 'Purchases are disabled for this account. Please contact support.'; end if;
  if public.purchases_restricted(uid) then raise exception 'Purchases are paused on this account while VYBE checks recent payment activity. Contact support if this is a mistake.'; end if;
  if p_provider is null or p_provider not in ('payfast','ozow') then raise exception 'Choose PayFast or Ozow'; end if;
  if p_idem is null or char_length(p_idem) < 8 then raise exception 'Missing idempotency key'; end if;
  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) not between 1 and 10 then raise exception 'Choose at least one ticket'; end if;
  if (select count(distinct e->>'ticket_type_id') from jsonb_array_elements(p_items) e) <> jsonb_array_length(p_items) then raise exception 'Each ticket type can appear once per order'; end if;

  select * into ord from public.orders where buyer = uid and idempotency_key = p_idem;
  if found then return jsonb_build_object('id', ord.id, 'status', ord.status, 'total_cents', ord.total_cents, 'fee_cents', ord.fee_cents, 'subtotal_cents', ord.subtotal_cents, 'expires_at', ord.expires_at); end if;

  select * into cfg from public.platform_config where id;
  select * into ev from public.events e where e.id = p_event;
  if not found or ev.status <> 'active' or not public.can_view_event(ev) then raise exception 'This event is not available'; end if;
  if coalesce(ev.ends_at, ev.starts_at + interval '6 hours') < now() then raise exception 'This event has ended'; end if;

  if (select count(*) from public.orders where buyer = uid and created_at > now() - interval '10 minutes') >= 6 then raise exception 'Too many attempts. Please wait a few minutes.'; end if;
  if (select count(*) from public.orders where buyer = uid and created_at > now() - interval '24 hours') >= 30 then raise exception 'Daily purchase limit reached.'; end if;
  if (select count(*) from public.orders where buyer = uid and status = 'pending' and expires_at > now()) >= 3 then raise exception 'Finish or cancel your pending orders first.'; end if;

  -- Lock ticket types in a fixed order (by id) so two orders for the same types can never deadlock.
  for it in select e from jsonb_array_elements(p_items) e order by e->>'ticket_type_id' loop
    q := (it->>'qty')::integer;
    select * into tt from public.ticket_types where id = (it->>'ticket_type_id')::uuid and event_id = p_event for update;
    if not found then raise exception 'Unknown ticket type'; end if;
    if tt.status <> 'active' then raise exception '% is not on sale', tt.name; end if;
    if tt.sales_start is not null and tt.sales_start > now() then raise exception '% is not on sale yet', tt.name; end if;
    if tt.sales_end is not null and tt.sales_end < now() then raise exception 'Sales for % have closed', tt.name; end if;
    if q is null or q < 1 or q > tt.max_per_order then raise exception 'You can buy 1 to % of %', tt.max_per_order, tt.name; end if;
    if public.ticket_units_taken(tt.id) + q > tt.quantity_total then raise exception '% is sold out', tt.name; end if;
    subtotal := subtotal + tt.price_cents::bigint * q;
    total_units := total_units + q * tt.group_size;
  end loop;
  if total_units > cfg.max_tickets_per_order then raise exception 'You can buy up to % tickets per order', cfg.max_tickets_per_order; end if;
  select count(*) into mine from public.tickets where owner = uid and event_id = p_event and status in ('valid','used');
  if mine + total_units > 20 then raise exception 'Ticket limit per person reached for this event'; end if;

  -- Paid sales need VYBE's review of the event; free tickets do not.
  if subtotal > 0 and cfg.require_sales_review and ev.sales_review <> 'approved' then
    raise exception 'Ticket sales for this event open once VYBE has reviewed it';
  end if;

  pol := public.fee_policy_for(p_event);
  if subtotal > 0 and pol.id is null then raise exception 'Ticket sales are not configured yet'; end if;
  snap := public.price_order(pol, subtotal, total_units, cfg.vat_registered, cfg.vat_rate_bps);
  if (snap->>'total_cents')::bigint > 0 and (snap->>'total_cents')::bigint < 500 then raise exception 'The minimum card/EFT payment is R5.00'; end if;

  -- A promoter link counts only for its own event, while active, and never for the promoter's own purchase.
  if coalesce(btrim(p_ref), '') <> '' then
    select * into link from public.promoter_links where code = upper(btrim(p_ref)) and event_id = p_event and active;
    if found and link.promoter = uid then perform public.risk_signal('self_referral', 'user', uid, jsonb_build_object('link', link.id)); link := null; end if;
  end if;
  insert into public.orders (buyer, event_id, provider, subtotal_cents, fee_cents, fee_vat_cents, total_cents, idempotency_key, expires_at,
                             fee_policy_id, pricing, commission_cents, commission_vat_cents, organizer_net_cents, referral_link_id)
  values (uid, p_event, case when subtotal = 0 then 'free' else p_provider end, subtotal, (snap->>'buyer_fee_cents')::bigint, (snap->>'buyer_fee_vat_cents')::bigint,
          (snap->>'total_cents')::bigint, p_idem, now() + make_interval(mins => cfg.hold_minutes),
          pol.id, snap, (snap->>'commission_cents')::bigint, (snap->>'commission_vat_cents')::bigint, (snap->>'organizer_net_cents')::bigint, case when subtotal > 0 then link.id end)
  returning * into ord;
  for it in select * from jsonb_array_elements(p_items) loop
    insert into public.order_items (order_id, ticket_type_id, qty, unit_price_cents)
    select ord.id, t.id, (it->>'qty')::integer, t.price_cents from public.ticket_types t where t.id = (it->>'ticket_type_id')::uuid;
  end loop;

  if ord.total_cents = 0 then perform public.issue_tickets(ord.id, 'free', null); select * into ord from public.orders where id = ord.id; end if;
  return jsonb_build_object('id', ord.id, 'status', ord.status, 'total_cents', ord.total_cents, 'fee_cents', ord.fee_cents, 'subtotal_cents', ord.subtotal_cents, 'expires_at', ord.expires_at);
end $$;

-- The original four-argument checkout (no promoter link) keeps working for existing clients.
create or replace function public.create_order(p_event uuid, p_items jsonb, p_provider text, p_idem text) returns jsonb
language sql security definer set search_path = '' as $$ select public.create_order(p_event, p_items, p_provider, p_idem, null::text) $$;

-- request_refund: material changes make earlier purchases refundable at once.
create or replace function public.request_refund(p_order uuid, p_reason text, p_tickets uuid[] default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare o public.orders; ev public.events; cfg public.platform_config; ids uuid[]; amt bigint := 0; r public.refunds; st text; bad integer; is_full boolean;
begin
  select * into o from public.orders where id = p_order for update;                          -- one refund decision at a time per order
  if not found or o.buyer <> auth.uid() then raise exception 'Order not found'; end if;
  if o.status not in ('paid','partially_refunded') then raise exception 'This order cannot be refunded'; end if;
  if exists (select 1 from public.refunds where order_id = o.id and status in ('requested','approved','processing','manual_required')) then raise exception 'A refund for this order is already in progress'; end if;
  select * into ev from public.events where id = o.event_id;
  select * into cfg from public.platform_config where id;
  if p_tickets is null or cardinality(p_tickets) = 0 then
    select array_agg(id) into ids from public.tickets where order_id = o.id and status = 'valid';
  else
    ids := p_tickets;
    select count(*) into bad from unnest(ids) x where not exists (select 1 from public.tickets t where t.id = x and t.order_id = o.id and t.status = 'valid');
    if bad > 0 then raise exception 'Some tickets cannot be refunded (already used, refunded or not yours)'; end if;
  end if;
  if ids is null or cardinality(ids) = 0 then raise exception 'There is nothing left to refund on this order'; end if;
  select coalesce(sum(case when tt.group_size > 1 then tt.price_cents / tt.group_size else tt.price_cents end), 0) into amt
    from public.tickets t join public.ticket_types tt on tt.id = t.ticket_type_id where t.id = any (ids);
  amt := least(amt, o.subtotal_cents - least(o.refunded_cents, o.subtotal_cents));
  if amt <= 0 and o.subtotal_cents > 0 then raise exception 'There is nothing left to refund on this order'; end if;
  is_full := not exists (select 1 from public.tickets t where t.order_id = o.id and t.status = 'valid' and t.id <> all (ids)) and o.refunded_cents = 0 and not exists (select 1 from public.tickets t where t.order_id = o.id and t.status <> 'valid');
  -- After a material change (new date or venue, or one the organiser declared) earlier buyers get their money back at once,
  -- service fee included when nothing else on the order was used or refunded.
  if ev.material_change_at is not null and o.paid_at is not null and o.paid_at < ev.material_change_at and not exists (select 1 from public.tickets t where t.order_id = o.id and t.status = 'used') then
    st := 'approved';
  else
    st := case when now() <= ev.starts_at - make_interval(hours => cfg.buyer_refund_hours) then 'approved' else 'requested' end;
  end if;
  insert into public.refunds (order_id, requested_by, kind, status, ticket_ids, ticket_amount_cents, fee_amount_cents, reason, decided_at)
  values (o.id, auth.uid(), 'buyer_request', st, ids, amt, case when is_full and ev.material_change_at is not null and o.paid_at < ev.material_change_at then o.fee_cents else 0 end,
          left(coalesce(p_reason, ''), 500), case when st = 'approved' then now() end)
  returning * into r;
  return jsonb_build_object('id', r.id, 'status', r.status, 'ticket_amount_cents', r.ticket_amount_cents, 'full', is_full);
end $$;

-- Payout holds from the risk engine.
create or replace function public.request_payout(p_org uuid default null) returns uuid
language plpgsql security definer set search_path = '' as $$
declare bal jsonb; acct public.payout_accounts; new_id uuid; u uuid := case when p_org is null then auth.uid() end; amt bigint; cfg public.platform_config;
begin
  if not public.can_view_finance(p_org, u) or (p_org is not null and coalesce(public.org_role(p_org) in ('owner','admin'), false) is false and not public.is_admin()) then raise exception 'forbidden' using errcode = '42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended('payout:' || coalesce(p_org::text, u::text), 0));   -- one request at a time per payee
  select * into cfg from public.platform_config where id;
  select * into acct from public.payout_accounts where organization_id is not distinct from p_org and user_id is not distinct from u;
  if not found or acct.status <> 'verified' then raise exception 'Add and verify a payout account first'; end if;
  if public.payout_on_hold(p_org, u) then raise exception 'Payouts are on hold while VYBE reviews recent activity. You can see the hold and appeal it under Finance.'; end if;
  if acct.updated_at > now() - make_interval(hours => cfg.payout_account_cooloff_hours) then
    raise exception 'Payout details changed recently. For your security, payouts resume % hours after a change.', cfg.payout_account_cooloff_hours;
  end if;
  if exists (select 1 from public.payouts where status in ('requested','approved') and organization_id is not distinct from p_org and user_id is not distinct from u) then raise exception 'You already have a payout in progress'; end if;
  bal := public.payout_balance(p_org); amt := (bal->>'available_cents')::bigint;
  if amt < (bal->>'min_payout_cents')::bigint or amt <= 0 then raise exception 'Available balance is below the minimum payout'; end if;
  insert into public.payouts (organization_id, user_id, amount_cents, requested_by) values (p_org, u, amt, auth.uid()) returning payouts.id into new_id;
  perform public.raise_exception_case('payout_awaiting_approval', new_id::text, 'low', jsonb_build_object('amount_cents', amt), null, null, new_id);
  return new_id;
end $$;

create or replace function public.admin_mark_payout_paid(p_payout uuid, p_reference text) returns void
language plpgsql security definer set search_path = '' as $$
declare p public.payouts; cfg public.platform_config; bal jsonb;
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  if coalesce(char_length(btrim(p_reference)), 0) < 4 then raise exception 'Enter the bank transfer reference'; end if;
  select * into cfg from public.platform_config where id;
  select * into p from public.payouts where id = p_payout for update;
  if not found or p.status <> 'approved' then raise exception 'Payout must be approved first'; end if;
  if p.requested_by = auth.uid() then raise exception 'You cannot confirm a payout you requested' using errcode = '42501'; end if;
  if public.payout_on_hold(p.organization_id, p.user_id) then raise exception 'This payee has an open payout hold; resolve the risk case first'; end if;
  if p.amount_cents >= cfg.payout_dual_control_cents and p.decided_by = auth.uid() then raise exception 'A second admin must confirm payouts of this size' using errcode = '42501'; end if;
  -- Re-check: refunds or chargebacks since approval may have reduced what is owed.
  bal := public.payout_balance_for(p.organization_id, p.user_id);
  if (bal->>'available_cents')::bigint + p.amount_cents < p.amount_cents then
    perform public.raise_exception_case('payout_exceeds_balance', p.id::text, 'critical', bal || jsonb_build_object('payout_cents', p.amount_cents), null, null, p.id);
    raise exception 'This payout is now larger than the available balance; it has been flagged for review';
  end if;
  update public.payouts set status = 'paid', paid_at = now(), bank_reference = left(btrim(p_reference), 120) where id = p_payout returning * into p;
  insert into public.ledger_entries (organization_id, payee_user, payout_id, kind, amount_cents, note) values (p.organization_id, p.user_id, p.id, 'payout', -p.amount_cents, 'Payout ' || coalesce(p_reference, ''));
  perform public.post_journal('payout', 'payout:' || p.id, jsonb_build_object('payout', p.id), jsonb_build_array(
    jsonb_build_object('account', 'organizer_payable', 'amount', p.amount_cents, 'org', p.organization_id, 'user', p.user_id),
    jsonb_build_object('account', 'platform_cash', 'amount', -p.amount_cents)), 'Payout ' || left(btrim(p_reference), 120));
  insert into public.audit_log (actor, action, entity_type, entity_id, detail) values (auth.uid(), 'payout.paid', 'payout', p.id, jsonb_build_object('amount_cents', p.amount_cents, 'approved_by', p.decided_by));
  perform public.notify(coalesce(p.user_id, p.requested_by), 'payout_update', null, 'payout', p.id, 'payout:' || p.id || ':paid');
end $$;

-- ---------------------------------------------------------------- 5. exports (no buyer contact details)
create or replace function public.event_sales_export(p_event uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  if not (public.is_admin() or public.can_manage_event(p_event)) then raise exception 'forbidden' using errcode = '42501'; end if;
  insert into public.audit_log (actor, action, entity_type, entity_id) values (auth.uid(), 'export.sales', 'event', p_event);
  return coalesce((select jsonb_agg(jsonb_build_object('order', left(o.id::text, 8), 'created_at', o.created_at, 'paid_at', o.paid_at, 'status', o.status, 'provider', o.provider,
           'tickets', (select count(*) from public.tickets t where t.order_id = o.id), 'ticket_subtotal_cents', o.subtotal_cents, 'buyer_fee_cents', o.fee_cents,
           'commission_cents', o.commission_cents, 'organizer_net_cents', o.organizer_net_cents, 'refunded_cents', o.refunded_cents,
           'promoter_code', (select l.code from public.promoter_links l where l.id = o.referral_link_id)) order by o.created_at)
    from public.orders o where o.event_id = p_event and o.status in ('paid', 'partially_refunded', 'refunded', 'disputed')), '[]'::jsonb);
end $$;
create or replace function public.event_door_list(p_event uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  if not (public.is_admin() or public.can_manage_event(p_event)) then raise exception 'forbidden' using errcode = '42501'; end if;
  insert into public.audit_log (actor, action, entity_type, entity_id) values (auth.uid(), 'export.door_list', 'event', p_event);
  return coalesce((select jsonb_agg(jsonb_build_object('holder', coalesce(nullif(p.display_name, ''), p.username), 'ticket_type', tt.name, 'status', t.status, 'checked_in_at', t.used_at) order by p.display_name, p.username)
    from public.tickets t join public.ticket_types tt on tt.id = t.ticket_type_id join public.profiles p on p.id = t.owner where t.event_id = p_event and t.status in ('valid', 'used')), '[]'::jsonb);
end $$;

-- ---------------------------------------------------------------- 6. scheduled housekeeping
do $$ begin
  begin create extension if not exists pg_cron; exception when others then null; end;
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('vybe-expire-orders', '*/5 * * * *', 'select public.expire_orders()');
    perform cron.schedule('vybe-release-refunds', '*/10 * * * *', 'select public.release_stuck_refunds()');
    perform cron.schedule('vybe-reconcile', '17 3 * * *', 'select public.finance_reconcile()');
  end if;
exception when others then null;
end $$;

-- ---------------------------------------------------------------- grants
revoke execute on function public.risk_signal(text, text, uuid, jsonb), public.payout_on_hold(uuid, uuid), public.purchases_restricted(uuid),
  public.notify_ticket_holders(uuid, text), public.reverse_referral(uuid, bigint, bigint, text) from public, anon, authenticated;
revoke execute on function public.my_payout_holds(uuid), public.appeal_payout_hold(bigint, text), public.admin_decide_risk_case(bigint, text, text),
  public.admin_set_risk_rule(text, boolean, integer, integer, text), public.declare_material_change(uuid, text), public.review_eligibility(uuid),
  public.submit_event_review(uuid, integer, text), public.respond_to_review(uuid, text), public.admin_moderate_review(uuid, text, text), public.event_review_summary(uuid),
  public.submit_complaint(uuid, text, text), public.reply_complaint(uuid, text), public.escalate_complaint(uuid), public.admin_close_complaint(uuid, text),
  public.create_promoter_link(uuid, text, integer), public.set_promoter_link_active(uuid, boolean), public.my_promoter_earnings(),
  public.event_sales_export(uuid), public.event_door_list(uuid), public.create_order(uuid, jsonb, text, text, text) from public, anon;
grant execute on function public.my_payout_holds(uuid), public.appeal_payout_hold(bigint, text), public.admin_decide_risk_case(bigint, text, text),
  public.admin_set_risk_rule(text, boolean, integer, integer, text), public.declare_material_change(uuid, text), public.review_eligibility(uuid),
  public.submit_event_review(uuid, integer, text), public.respond_to_review(uuid, text), public.admin_moderate_review(uuid, text, text), public.event_review_summary(uuid),
  public.submit_complaint(uuid, text, text), public.reply_complaint(uuid, text), public.escalate_complaint(uuid), public.admin_close_complaint(uuid, text),
  public.create_promoter_link(uuid, text, integer), public.set_promoter_link_active(uuid, boolean), public.my_promoter_earnings(),
  public.event_sales_export(uuid), public.event_door_list(uuid), public.create_order(uuid, jsonb, text, text, text) to authenticated;
do $$ declare f record; begin
  for f in select p.oid::regprocedure as sig from pg_proc p
            where p.pronamespace = 'public'::regnamespace and p.prorettype in ('trigger'::regtype, 'event_trigger'::regtype) loop
    execute format('revoke execute on function %s from public, anon, authenticated', f.sig);
  end loop;
end $$;

commit;

select item, ok from (values
  ('finance views closed to outsiders (security fix)', (select prosrc from pg_proc where proname = 'can_view_finance') like '%coalesce%'),
  ('risk rules seeded; cases are admin-only', (select count(*) from public.risk_rules) >= 10 and (select relrowsecurity from pg_class where oid = 'public.risk_cases'::regclass)),
  ('risk signals cannot be raised over the API', not has_function_privilege('authenticated', 'public.risk_signal(text, text, uuid, jsonb)', 'execute')),
  ('reviews only through the eligibility check', to_regclass('public.event_reviews') is not null and not has_table_privilege('authenticated', 'public.event_reviews', 'insert') and has_function_privilege('authenticated', 'public.submit_event_review(uuid, integer, text)', 'execute')),
  ('complaints and promoter links', to_regclass('public.event_complaints') is not null and to_regclass('public.promoter_links') is not null and has_function_privilege('authenticated', 'public.create_order(uuid, jsonb, text, text, text)', 'execute')),
  ('journal knows promoter payable', (select pg_get_constraintdef(oid) from pg_constraint where conname = 'journal_lines_account_known') like '%promoter_payable%'),
  ('every journal entry balances', not exists (select 1 from public.journal_lines group by entry_id having sum(amount_cents) <> 0)),
  ('no trigger function callable over the API', not exists (select 1 from pg_proc p where p.pronamespace = 'public'::regnamespace and p.prorettype = 'trigger'::regtype and (has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute'))))
) as v(item, ok);
-- END OF MIGRATION 28
